fn parameter_type(op: VecOp, index: usize, ty: &Type) -> bool {
    match (op, index) {
        (VecOp::WithCapacity, 0) | (VecOp::Get | VecOp::ReserveExact | VecOp::Set, 1) => {
            *ty == Type::Usize
