        }
        ty if allow_owned && crate::map_ops::ast_collection(ty) => {
            let (name, arguments) = collection_constructor(ty);
            Ok(ExpandedDefaultCost {
                bytes: 2 * std::mem::size_of::<Expr>()
                    + name.len()
                    + std::mem::size_of_val(arguments),
                string_bytes: name.len(),
