                        cost.add_identity_carriers(nested.identity_carriers)?;
                        identity_slots = checked_builder_sum(
                            identity_slots,
                            nested.identity_slots.checked_add(1).ok_or_else(|| {
                                vec![limit_error("builder_bytes", active_builder_limit())]
                            })?,
                        )?;
